import { useEffect, useState } from "react";
import "./css/Festval_CardItem.css";
import axios from "axios";

const Festval_card_item = ({article}) => {

  const {title, date, address, urlImage} = article;
  
    return(
        <div className='card_list_item'>            
            <img className='media_header' src={urlImage} alt="com" />
            <div className="media_item">              
              <ul className="media_info">
                <li className="media_alram">
                    <span>준비중</span>
                </li>              
                <li className="media_title">
                    {title}
                </li>                
                <li className="media_date">
                  <span className="sub">기간</span>                  
                  <span>{date}</span>~<span>종료일</span>                  
                </li>
                <li className="media_address">
                  <span className="sub">장소</span>                  
                  <span>{address}</span>                  
                </li>
                <li className="media_link">
                  <a className="media_map" href="#">지도보기</a>
                  <a className="media_home" href="#">홈페이지</a>
                </li>
              </ul>              
            </div>
        </div>
    );
};

export default Festval_card_item;
